    Bug 2017605 - Try to fix intermittent comm/calendar/test/browser/recurrence/browser_weeklyUntil.js | testWeeklyUntilRecurrence - Uncaught exception in test - calendar-event-box at day=1, index=1 did not appear in time. r=tobyp

    Differential Revision: https://phabricator.services.mozilla.com/D306713

diff --git a/calendar/test/ItemEditingHelpers.sys.mjs b/calendar/test/ItemEditingHelpers.sys.mjs
index b1017bb35e2..d7190e2aece 100644
--- a/calendar/test/ItemEditingHelpers.sys.mjs
+++ b/calendar/test/ItemEditingHelpers.sys.mjs
@@ -388,6 +388,23 @@ export async function setData(dialogWindow, iframeWindow, data) {
  * @param {Window} dialogWindow
  */
 export async function saveAndCloseItemDialog(dialogWindow) {
+  let calendarObserver;
+  const itemSaved = new Promise(resolve => {
+    calendarObserver = {
+      QueryInterface: ChromeUtils.generateQI(["calIObserver"]),
+      onAddItem: resolve,
+      onModifyItem: resolve,
+      onDeleteItem() {},
+      onStartBatch() {},
+      onEndBatch() {},
+      onLoad() {},
+      onError() {},
+      onPropertyChanged() {},
+      onPropertyDeleting() {},
+    };
+    cal.manager.addCalendarObserver(calendarObserver);
+  });
+
   const dialogClosing = BrowserTestUtils.domWindowClosed(dialogWindow);
   synthesizeMouseAtCenter(
     dialogWindow.document.getElementById("button-saveandclose"),
@@ -396,6 +413,8 @@ export async function saveAndCloseItemDialog(dialogWindow) {
   );
   await dialogClosing;
   Assert.report(false, undefined, undefined, "Item dialog closed");
+  await itemSaved;
+  cal.manager.removeCalendarObserver(calendarObserver);
   await new Promise(resolve => setTimeout(resolve));
 }
